for f,o,n in R:
    p=f'm/{f}.txt'; t=open(p,encoding='utf8').read()
    if o not in t: print('INTROUVABLE',f,o[:70]); continue
    t=t.replace(o,n,1); open(p,'w',encoding='utf8').write(t)
# global compact notation
import glob
for p in glob.glob('m/m*.txt'):
    t=open(p,encoding='utf8').read()
    t2=t.replace('2 HRZE / 4 HR','2HRZE/4HR').replace('2 HRE / 7 HR','2HRE/7HR')
    if t2!=t: open(p,'w',encoding='utf8').write(t2)
